<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nym · Resumen completo</title><link rel="stylesheet" href="assets/dashboard.css?v=20260910-9"><style>body{background:#101411;color:#e4ece3}main{max-width:1900px}.toolbar{display:flex;gap:12px;align-items:center;margin-bottom:16px}.toolbar input{flex:1;background:#171d18;border:1px solid #394638;border-radius:6px;color:#e4ece3;padding:10px 12px;font:inherit}.toolbar input:focus{outline:2px solid #c4f76a}.table-wrap{overflow:auto;border:1px solid #303b30;border-radius:8px;background:#171d18}.table-wrap table{width:100%;border-collapse:collapse;min-width:1600px;font-size:12px}.table-wrap th,.table-wrap td{padding:8px 10px;border-bottom:1px solid #2d382c;text-align:left;white-space:nowrap}.table-wrap th{position:sticky;top:0;color:#a4b2a4;background:#1a211a;font-weight:500}.table-wrap tr:hover{background:#202a20}.muted{color:#91a190}.count{font-size:13px;color:#a4b2a4}.error{color:#f4bd73}</style></head><body><main><header><div><h1>nym <span>Resumen completo</span></h1><span class="subtitle">Datos de todos los nodos</span></div></header><div class="toolbar"><input id="search" type="search" placeholder="Buscar por ID, moniker, identity, país, versión…" autocomplete="off"><span id="count" class="count">Consultando…</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Moniker</th><th>Identity key</th><th>País</th><th>Tipo</th><th>Versión</th><th>Rendimiento</th><th>Activo 24h</th><th>Delegaciones</th><th>Operating cost</th><th>Profit margin</th><th>Total stake</th><th>Saturación</th><th>TAC</th><th>Config.</th><th>Estado</th></tr></thead><tbody id="rows"><tr><td colspan="16" class="loading">Consultando API…</td></tr></tbody></table></div></main><script>
const API='https://api.nym.spectredao.net/api/v1/nodes?limit=1000&page=1', EPOCH='https://api.nym.spectredao.net/api/v1/current-interval', rows=document.getElementById('rows'), search=document.getElementById('search'), count=document.getElementById('count'); let data=[];
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])), n=v=>{let x=Number(v);return Number.isFinite(x)?x:null}, pct=v=>{let x=n(v);return x===null?'—':((x<=1?x*100:x).toFixed(2)+'%')};
function stake(v){let x=n(v);return x===null?'—':(x/1e6).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2})+' NYM'}
function value(o,...keys){for(const k of keys){let v=k.split('.').reduce((a,p)=>a?.[p],o);if(v!==undefined&&v!==null)return v}return null}
function render(){let q=search.value.trim().toLowerCase(), filtered=data.filter(x=>JSON.stringify(x).toLowerCase().includes(q)); rows.innerHTML=filtered.map(x=>{let d=value(x,'description')||{}, r=value(x,'rewarding_details')||{}, c=r.cost_params||{}, a=value(x,'active_set','active_set_frequency')||{};return `<tr><td>${esc(value(x,'node_id','id'))}</td><td>${esc(value(x,'self_description.moniker','self_description.moniker_name','moniker','description.moniker'))}</td><td>${esc(value(x,'identity_key','identityKey'))}</td><td>${esc(value(x,'geoip.country','geoip.country_name','geoip.country_code','country','location.country','location.country_code'))}</td><td>${(() => { const role=value(x,'description.declared_role','declared_role','data.declared_role')||{}; return (role.mixnode===true||role.mixnode==='true')?'Mixnode':((role.mixnode===false||role.mixnode==='false')?'Gateway':value(x,'node_type','kind','type')||'—'); })()}</td><td>${esc(value(x,'build_information.build_version','description.build_information.build_version','version'))}</td><td>${pct(value(x,'performance_score','performance'))}</td><td>${a.period_hours===24?pct(a.frequency_percentage/100):'—'}</td><td>${value(r,'unique_delegations','delegations')??'—'}</td><td>${c.interval_operating_cost?.denom==='unym'?stake(c.interval_operating_cost.amount):'—'}</td><td>${pct(c.profit_margin_percent)}</td><td>${stake(value(x,'total_stake'))}</td><td>${pct(value(x,'uncapped_saturation','stake_saturation'))}</td><td>${value(x,'accepted_tnc')===true?'Sí':value(x,'accepted_tnc')===false?'No':'—'}</td><td>${pct(value(x,'config_score'))}</td><td>${(() => { const last=value(x,'last_rewarded_epoch','rewarding_details.last_rewarded_epoch','status.last_rewarded_epoch','data.last_rewarded_epoch') ?? value(e,'last_rewarded_epoch','rewarding_details.last_rewarded_epoch','status.last_rewarded_epoch','data.last_rewarded_epoch'); const state=window.currentEpoch!==null&&Number(last)===(window.currentEpoch-1)?'Activo':window.currentEpoch!==null&&last!==null?'Inactivo':'—'; return state; })()}</td></tr>`}).join('')||'<tr><td colspan="16" class="loading">Sin resultados</td></tr>'; count.textContent=`${filtered.length} de ${data.length} nodos`}
async function load(){try{let [r,er]=await Promise.all([fetch(API,{cache:'no-store'}),fetch(EPOCH,{cache:'no-store'}).catch(()=>null)]),j=await r.json(),ej=er&&er.ok?await er.json():{};if(!r.ok)throw Error();ej=Array.isArray(ej)?(ej[0]||{}):ej;window.currentEpoch=Number(ej.interval?.total_elapsed_epochs??ej.total_elapsed_epochs??ej.id??ej.epoch_id??ej.interval_id??ej.current_epoch??ej.epoch??ej.current_interval?.id??ej.interval?.id??ej.data?.id??NaN);if(!Number.isFinite(window.currentEpoch))window.currentEpoch=null;data=Array.isArray(j)?j:(j.nodes||j.data||j.nym_nodes||[]);if(!Array.isArray(data))data=[];render()}catch(e){rows.innerHTML='<tr><td colspan="16" class="error">No fue posible consultar la API.</td></tr>';count.textContent='Error de consulta'}}search.addEventListener('input',render);load();
</script></body></html>
